<?php
if(!defined('IN_LAYOUT')){header('Location: ../dashboard/layout.php?page=survey_history');exit;}
if(($role??'')!=='student'){http_response_code(403);echo '<p>This survey history is available only to the student who submitted it.</p>';return;}
require_once __DIR__.'/../includes/surveys/annual.php';require_once __DIR__.'/../includes/surveys/assessment_profile.php';
$shE=static fn($v)=>htmlspecialchars((string)($v??''),ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$shYear=is_string($_GET['school_year']??null)?$_GET['school_year']:'';$shPage=is_scalar($_GET['history_page']??1)?max(1,(int)($_GET['history_page']??1)):1;$shData=SurveyAnnual::history($db,(int)$uid,$shYear,$shPage);$shCurrent=SurveyAnnual::year($db,(int)$uid);$shSelected=null;$shError='';
$shLabels=['mi'=>'Multiple Intelligence','ls'=>'Learning Style','ls_intermediate'=>'Learning Style (Intermediate)'];
if(isset($_GET['assessment'])){try{$shId=filter_var($_GET['assessment'],FILTER_VALIDATE_INT);$shKind=is_string($_GET['kind']??null)?$_GET['kind']:'';if(!$shId||!isset($shLabels[$shKind]))throw new RuntimeException('Unavailable');$shSelected=AssessmentProfile::load($db,$shKind,(int)$shId);if($shSelected['user_id']!==(int)$uid)throw new RuntimeException('Unavailable');}catch(Throwable $e){$shSelected=null;$shError='This saved survey is unavailable.';http_response_code(404);}}
?><link rel="stylesheet" href="../assets/css/survey-annual.css?v=20261029-1"><section class="sa-history"><header><p>STUDENT PORTAL · YEARLY ASSESSMENTS</p><h1>Survey school-year history</h1><p>Each school year keeps its own assessment. Saved results below are read-only.</p><a class="sa-button" href="layout.php?page=dashboard">Back to overview</a></header>
<?=SurveyAnnual::notice($shCurrent)?>
<?php if($shError):?><p role="alert"><?=$shE($shError)?></p><?php endif;?>
<section class="sa-panel"><form class="sa-filter" method="get" action="layout.php"><input type="hidden" name="page" value="survey_history"><label>School year<select name="school_year"><option value="">All school years</option><?php foreach($shData['years'] as $year):$value=$year===''?'legacy':$year;?><option value="<?=$shE($value)?>" <?=$shYear===$value?'selected':''?>><?=$shE($year?:'School year not recorded')?></option><?php endforeach;?></select></label><button class="sa-button">Apply filter</button><a class="sa-button" href="layout.php?page=survey_history">Clear</a></form><div class="sa-table-wrap"><table><thead><tr><th>School year</th><th>Assessment</th><th>Submitted</th><th></th></tr></thead><tbody><?php foreach($shData['rows'] as $row):?><tr><td><?=$shE($row['school_year']?:'Not recorded')?></td><td><?=$shE($shLabels[$row['kind']])?></td><td><?=$shE($row['completed_at']?:'Not recorded')?></td><td><a class="sa-button" href="layout.php?page=survey_history&amp;kind=<?=$shE($row['kind'])?>&amp;assessment=<?=(int)$row['id']?>#surveySavedResult">View results</a></td></tr><?php endforeach;?><?php if(!$shData['rows']):?><tr><td colspan="4">No survey results in this scope.</td></tr><?php endif;?></tbody></table></div><footer class="sa-pagination"><span><?=$shData['total']?> assessments · Page <?=$shData['page']?> of <?=$shData['pages']?></span><div><?php foreach(['Previous'=>-1,'Next'=>1] as $label=>$offset):if($shData['page']+$offset>=1&&$shData['page']+$offset<=$shData['pages']):?><a class="sa-button" href="layout.php?page=survey_history&amp;school_year=<?=$shE($shYear)?>&amp;history_page=<?=$shData['page']+$offset?>"><?=$label?></a><?php endif;endforeach;?></div></footer></section>
<p>Older results without a recorded school year are kept under “Not recorded”. Their year has not been guessed.</p>
<?php if($shSelected):?><section class="sa-panel sa-results" id="surveySavedResult" tabindex="-1"><p>READ-ONLY SAVED RESULTS</p><h2><?=$shE($shLabels[$shSelected['assessment_type']])?> · <?=$shE($shSelected['school_year']?:'School year not recorded')?></h2><dl><?php foreach(['Student'=>$shSelected['student'],'Student ID'=>$shSelected['student_id'],'Grade / year'=>$shSelected['grade_level'],'Submitted'=>$shSelected['submitted']] as $label=>$value):?><div><dt><?=$label?></dt><dd><?=$shE($value?:'Not recorded')?></dd></div><?php endforeach;?></dl><div class="sa-score-grid"><?php foreach($shSelected['scores'] as $score):?><article><h3><?=$shE($score['name'])?></h3><strong><?=(int)$score['score']?>%</strong><progress max="100" value="<?=(int)$score['score']?>" aria-label="<?=$shE($score['name'])?> share of recorded scores"></progress></article><?php endforeach;?></div><p>Percentages show each category’s share of the saved scores. They do not measure intelligence or limit how you can learn.</p><?php if(!$shSelected['profile_frozen']):?><p>This older result did not record a school-profile snapshot; its identity labels use the existing account record.</p><?php endif;?></section><script>requestAnimationFrame(()=>{const saved=document.getElementById('surveySavedResult');saved.focus({preventScroll:true});saved.scrollIntoView({block:'start',behavior:'instant'});});</script><?php endif;?></section>
